package school.magiccodex.client;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;class HousingSearchGenerationTest{@Test void typingPagingCloseReconnectAndTimeoutInvalidateEarlierResponses(){var gate=new HousingSearchGeneration();long first=gate.next();assertTrue(gate.accepts(first));long changedText=gate.next();assertFalse(gate.accepts(first));long nextPage=gate.next();assertFalse(gate.accepts(changedText));long closed=gate.next();assertFalse(gate.accepts(nextPage));long reconnected=gate.next();assertFalse(gate.accepts(closed));assertTrue(gate.accepts(reconnected));}}
